    63→/**
    64→ * Muestra u oculta tablas según la existencia de datos.
    65→ *
    66→ * @returns {void}
    67→ * @author Andres Morales
    68→ */
    69→function validarDatos() {
    70→    var tiene_filtros_aplicados = verificarFiltrosAplicados();
    71→
    72→    if (datos_ids.length == 0) {
    73→        if (tiene_filtros_aplicados) {
    74→            // Si hay filtros aplicados, mostrar los controles pero con empty state en la tabla
    75→            $('#tabla-contenido').removeClass('d-none');
    76→            $('#tabla-sin-contenido').addClass('d-none');
    77→            mostrarEstadoVacioFiltros();
    78→        } else {
    79→            // Si no hay filtros, ocultar todo y mostrar el empty state general
    80→            $('#tabla-contenido').addClass('d-none');
    81→            $('#tabla-sin-contenido').removeClass('d-none');
    82→        }
    83→    } else {
    84→        $('#tabla-contenido').removeClass('d-none');
    85→        $('#tabla-sin-contenido').addClass('d-none');
    86→        ocultarEstadoVacioFiltros();
    87→    }
    88→}
    89→
    90→/**
    91→ * Verifica si hay filtros aplicados en la tabla.
    92→ *
    93→ * @returns {boolean}
    94→ * @author Andres Morales
    95→ */
    96→function verificarFiltrosAplicados() {
    97→    var valor_filtro_estado = $('#filtro_estado_tarea').val();
    98→    var valor_filtro_fecha = $('#filtro_fecha').val();
    99→    var valor_buscador = $('.dt-search input').val();
   100→
   101→    return (valor_filtro_estado && valor_filtro_estado != '0') ||
   102→           (valor_filtro_fecha && valor_filtro_fecha.trim() !== '') ||
   103→           (valor_buscador && valor_buscador.trim() !== '');
   104→}
   105→
   106→/**
   107→ * Muestra el empty state cuando hay filtros aplicados pero no hay resultados.
   108→ *
   109→ * @returns {void}
   110→ * @author Andres Morales
   111→ */
   112→function mostrarEstadoVacioFiltros() {
   113→    var contenedor_tabla = $('#tabla-tareas-pendientes_wrapper');
   114→
   115→    if (contenedor_tabla.find('.estado-vacio-filtros').length === 0) {
   116→        var html_estado_vacio = `
   117→            <div class="estado-vacio-filtros w-100 text-center p-10">
   118→                <p class=""><i class="bi bi-funnel text-gray-60 icono-estado-vacio"></i></p>
   119→                <p class="pb-4 text-headline-5 fw-bold text-gray-30">No se encontraron resultados con los filtros aplicados.</p>
   120→            </div>
   121→        `;
   122→        contenedor_tabla.find('table').hide();
   123→        contenedor_tabla.append(html_estado_vacio);
   124→    }
   125→}
   126→
   127→/**
   128→ * Oculta el empty state de filtros cuando hay resultados.
   129→ *
   130→ * @returns {void}
   131→ * @author Andres Morales
   132→ */
   133→function ocultarEstadoVacioFiltros() {
   134→    var contenedor_tabla = $('#tabla-tareas-pendientes_wrapper');
   135→    contenedor_tabla.find('.estado-vacio-filtros').remove();
   136→    contenedor_tabla.find('table').show();
   137→}
