   139→/**
   140→ * Renderiza una tarjeta para un proceso con agendas.
   141→ *
   142→ * @param {Object} dato - Objeto de proceso con agendas.
   143→ * @returns {string} HTML generado con la estructura de la tarjeta del proceso.
   144→ * @author Andres Morales
   145→ */
   146→function renderizarProceso(dato) {
   147→    let es_primera_columna = false;
   148→    let clase_boton = es_primera_columna ? 'accordion-button shadow-none text-body-1' : 'accordion-button shadow-none text-body-1 collapsed';
   149→    let area_expandida = es_primera_columna ? 'true' : 'false';
   150→    let clase_para_colapsado = es_primera_columna ? 'accordion-collapse collapse show' : 'accordion-collapse collapse';
   151→    let mostrar_empresa = (dato?.mostrar_logo_aplicante === true) || (Number(dato?.mostrar_logo_aplicante) === 1);
   152→    let empresa_html = mostrar_empresa ? `
   153→                    <div class="col-12 d-flex">
   154→                        <i class="my-auto bi bi-buildings-fill text-body-3 text-gray-30"></i>
   155→                        <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">Empresa:</h5>
   156→                        <img class="my-auto border rounded" width="24px" height="24px" src="/empresas-logo/${dato?.empresa_id}" alt="${dato?.empresa?.nombre_comercial}" onerror="this.onerror=null;"/>
   157→                        <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">${dato?.empresa?.nombre_comercial}</h5>
   158→                    </div>
   159→    ` : '';
   160→
   161→    let total_agendas = (dato?.agendas && dato.agendas.length > 0) ? dato.agendas.length : 1;
   162→
   163→    return `
   164→        <div class="card">
   165→            <div class="card-body">
   166→                <div class="row mb-3">
   167→                    <div class="col-12">
   168→                        <h5 class="card-title text-body-1 fw-bolder text-gray-10">${dato.nombre}</h5>
   169→                    </div>
   170→                    ${empresa_html}
   171→                </div>
   172→                <div class="accordion" id="accordionProceso${dato?.id}">
   173→                    <div class="accordion-item">
   174→                        <h2 class="accordion-header">
   175→                            <button class="${clase_boton} d-flex justify-content-between align-items-center" type="button" data-bs-toggle="collapse" data-bs-target="#collapseProceso${dato.id}" aria-expanded="${area_expandida}" aria-controls="collapseProceso${dato.id}">
   176→                                <span>Ver tareas pendientes</span>
   177→                                ${total_agendas > 0 ? `<span class="badge bg-danger rounded-pill text-label-2">${total_agendas}</span>` : ''}
   178→                            </button>
   179→                        </h2>
   180→                        <div id="collapseProceso${dato.id}" class="${clase_para_colapsado}" data-bs-parent="#accordionProceso${dato?.id}">
   181→                            <div class="accordion-body">
   182→                                <h1 class="text-headline-5 fw-bloder text-gray-10">Pruebas psicométricas</h1>
   183→                                <div class="row gap-4 m-0">${procesarAgendas(dato?.agendas)}</div>
   184→                            </div>
   185→                        </div>
   186→                    </div>
   187→                </div>
   188→            </div>
   189→        </div>
   190→    `;
   191→}
   192→
   193→/**
   194→ * Renderiza una tarjeta para una vacante con etapas.
   195→ *
   196→ * @param {Object} dato - Objeto de vacante con etapas.
   197→ * @returns {string} HTML generado con la estructura de la tarjeta de la vacante.
   198→ * @author Andres Morales
   199→ * @author Andres Gonzalez
   200→ * @author José Manuel Jiménez
   201→ */
   202→function renderizarVacante(dato) {
   203→    let es_primera_columna = false;
   204→    let clase_boton = es_primera_columna ? 'accordion-button shadow-none text-body-1' : 'accordion-button shadow-none text-body-1 collapsed';
   205→    let area_expandida = es_primera_columna ? 'true' : 'false';
   206→    let clase_para_colapsado = es_primera_columna ? 'accordion-collapse collapse show' : 'accordion-collapse collapse';
   207→    let mostrar_empresa = dato?.empresa !== null && dato?.empresa !== undefined;
   208→
   209→    let etapa_actual = dato.etapa_actual || 0;
   210→    let total_etapas = dato.total_etapas || 0;
   211→    let porcentaje_progreso = (etapa_actual / total_etapas) * 100;
   212→
   213→    let total_agendas = 0;
   214→    let total_etapas_activas = 0;
   215→
   216→    if (dato?.etapas && dato.etapas.length > 0) {
   217→        dato.etapas.forEach((etapa) => {
   218→            var nombre_normalizado = normalizarNombreEtapa(etapa.nombre);
   219→            if (nombre_normalizado === 'PRUEBASPSICOMETRICAS' && etapa.agendas && etapa.agendas.length > 0) {
   220→                total_agendas += etapa.agendas.length;
   221→            } else if (nombre_normalizado !== 'PRUEBASPSICOMETRICAS' && etapa.activa == 1) {
   222→                if (nombre_normalizado === 'VIDEOENTREVISTA') {
   223→                    if (etapa.usuarios_vacantes[0].etapa_video_entrevista_completa != true) {
   224→                        total_etapas_activas++;
   225→                    }
   226→                    let solicita_formato = obtenerConfiguracionPorLlave(etapa.configuraciones, 'solicitar_formato_videoentrevista');
   227→                    if (solicita_formato == '1') {
   228→                        let formato_entrevista = etapa.usuarios_vacantes[0].formato_entrevista;
   229→                        let completo_formato_entrevista = formato_entrevista && formato_entrevista.descripcion_vacante !== null;
   230→                        if (completo_formato_entrevista == null) {
   231→                            total_etapas_activas++;
   232→                        }
   233→                    }
   234→                } else {
   235→                    total_etapas_activas++;
   236→                }
   237→            } else {
   238→                total_etapas_activas++;
   239→            }
   240→        });
   241→    }
   242→
   243→    let total_tareas_alerta = total_agendas > 0 ? total_agendas : total_etapas_activas;
   244→
   245→    let titulo_tareas = total_agendas > 0
   246→        ? `Pruebas psicométricas (${total_agendas})`
   247→        : `Tareas de selección (${total_etapas_activas})`;
   248→
   249→    let empresa_html = mostrar_empresa ? `
   250→        <div class="col-12 d-flex">
   251→            <i class="my-auto bi bi-buildings-fill text-body-3 text-gray-30"></i>
   252→            <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">Empresa:</h5>
   253→            <img class="my-auto border rounded" width="24px" height="24px" src="/empresas-logo/${dato?.empresa_id}" alt="${dato?.empresa?.nombre_comercial}" onerror="this.onerror=null;"/>
   254→            <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">${dato?.empresa?.nombre_comercial}</h5>
   255→        </div>
   256→    ` : '';
   257→
   258→    let barra_progreso_html = `
   259→        <div class="col-12 mt-3">
   260→            ${crearProgressBar({
   261→                label: '<span class="text-body-3 fw-bolder mb-3"><i class="bi bi-bar-chart-steps me-2"></i>Etapa actual: ' + etapa_actual + ' de ' + total_etapas + '</span>',
   262→                height: '8px',
   263→                class_label: 'mb-1',
   264→                porcentaje: {
   265→                    porcentaje: porcentaje_progreso,
   266→                    texto: false
   267→                },
   268→                class: 'barra-progreso-etapa',
   269→                rounded: 'rounded-3',
   270→                rounded2: 'rounded-3'
   271→            })}
   272→        </div>
   273→    `;
   274→
   275→    return `
   276→        <div class="card">
   277→            <div class="card-body">
   278→                <div class="row mb-3">
   279→                    <div class="col-12">
   280→                        <h5 class="card-title text-body-1 fw-bolder text-gray-10">${dato.nombre_vacante}</h5>
   281→                    </div>
   282→                    ${empresa_html}
   283→                    ${barra_progreso_html}
   284→                </div>
   285→                <div class="accordion" id="accordionVacante${dato?.id}">
   286→                    <div class="accordion-item">
   287→                        <h2 class="accordion-header">
   288→                            <button class="${clase_boton} d-flex justify-content-between align-items-center" type="button" data-bs-toggle="collapse" data-bs-target="#collapseVacante${dato.id}" aria-expanded="${area_expandida}" aria-controls="collapseVacante${dato.id}">
   289→                                <span>Ver tareas pendientes</span>
   290→                                ${total_tareas_alerta > 0 ? `<span class="badge bg-danger rounded-pill text-label-2">${total_tareas_alerta}</span>` : ''}
   291→                            </button>
   292→                        </h2>
   293→                        <div id="collapseVacante${dato.id}" class="${clase_para_colapsado}" data-bs-parent="#accordionVacante${dato?.id}">
   294→                            <div class="accordion-body">
   295→                                ${total_tareas_alerta > 0 ? `<h1 class="text-headline-5 fw-bloder text-gray-10">${titulo_tareas}</h1>` : ''}
   296→                                <div class="row gap-4 m-0">${procesarEtapas(dato?.etapas, dato?.id)}</div>
   297→                            </div>
   298→                        </div>
   299→                    </div>
   300→                </div>
   301→            </div>
   302→        </div>
   303→    `;
   304→}
   305→
   306→/**
   307→ * Genera el HTML para mostrar una lista de agendas en tarjetas (cards) con su información detallada.
   308→ *
   309→ * @param {Array<Object>} agendas - Arreglo de objetos de agenda a procesar.
   310→ * @returns {string} HTML generado con la estructura de las tarjetas para cada agenda.
   311→ * @author Andres Morales
   312→ * @author Fahibram Cárcamo
   313→ * @author Andres Gonzalez
   314→ */
   315→function procesarAgendas(agendas) {
   316→    let estado_clases = {
   317→        '1': 'tag-filled-yellow',
   318→        '2': 'tag-filled-blue',
   319→        '3': 'tag-filled-green',
   320→        '4': 'tag-filled-red',
   321→        '5': 'tag-filled-gray',
   322→        '6': 'tag-filled-green'
   323→    };
   324→    let html = '';
   325→
   326→    if (!agendas || agendas.length === 0) {
   327→        return '<div class="col-12"><p class="text-center text-gray-30">No hay pruebas asignadas</p></div>';
   328→    }
   329→
   330→    let orden_estado = [2, 1, 3, 4];
   331→
   332→    agendas.sort((a, b) => {
   333→        let primer_estado = orden_estado.indexOf(Number(a.estado_id));
   334→        let segundo_estado = orden_estado.indexOf(Number(b.estado_id));
   335→        return (primer_estado === -1 ? orden_estado.length : primer_estado) - (segundo_estado === -1 ? orden_estado.length : segundo_estado);
   336→    });
   337→
   338→    agendas.forEach((agenda) => {
   339→        if (agenda.estado.nombre == 'Agendada') agenda.estado.nombre = 'Pendiente';
   340→        else if (agenda.estado.nombre == 'Sin pago') agenda.estado.nombre = 'Finalizada';
   341→
   342→        html += `
   343→            <div class="col p-0 columna-tarjeta-tarea">
   344→                <div class="card h-100">
   345→                    <div class="card-body d-flex flex-column cuerpo-tarjeta-tarea">
   346→                        <div class="w-100 d-flex flex-column row-gap-3">
   347→                            <div class="w-100 d-flex justify-content-between align-items-center">
   348→                                <h5 class="card-title text-headline-5 text-gray-10 fw-medium fw-bold m-0">${agenda?.prueba?.nombre ?? ''}</h5>
   349→                                <div class="d-flex flex-row">
   350→                                    ${
   351→                                        (estado_clases[agenda.estado_id])
   352→                                            ? crearTag({
   353→                                                texto: agenda?.estado?.nombre ?? '',
   354→                                                class: estado_clases[agenda.estado_id]
   355→                                            })
   356→                                            : ''
   357→                                    }
   358→                                    ${
   359→                                        (agenda?.estado_id == "4")
   360→                                            ? `<i
   361→                                                class="bi bi-info-circle-fill text-info ms-3 text-headline-3 pointer"
   362→                                                ${crearTooltip({
   363→                                                    placement: `top`,
   364→                                                    content: `Esta tarea ha expirado debido a que se ha superado el tiempo límite de entrega.`,
   365→                                                    toggle: `popover`
   366→                                                })}
   367→                                            ></i>`
   368→                                            : ''
   369→                                    }
   370→                                </div>
   371→                            </div>
   372→
   373→                            <div class="w-100 d-flex flex-column row-gap-2">
   374→                                <div class="w-100 d-flex justify-content-start">
   375→                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-clock me-2"></i>Tiempo estimo:&nbsp;${agenda?.prueba?.duracion ?? '0'}&nbsp;minutos</p>
   376→                                </div>
   377→                                <div class="w-100 d-flex justify-content-start">
   378→                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-circle-fill text-green-cta me-2"></i>Asignada:&nbsp;${formatearFecha(agenda?.fecha_inicio)}</p>
   379→                                </div>
   380→                                <div class="w-100 d-flex justify-content-start">
   381→                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-circle-fill text-red-cta me-2"></i>Expira:&nbsp;${formatearFecha(agenda?.fecha_cierre)}</p>
   382→                                </div>
   383→                            </div>
   384→                        </div>
   385→
   386→                        <div class="w-100">
   387→                            ${
   388→                                (agenda.estado_id == "1")
   389→                                    ? crearBoton({
   390→                                        clases: 'btn-primary w-100 d-flex justify-content-center',
   391→                                        texto: 'Responder',
   392→                                        onclick: `iniciarPruebaConDemograficas(${agenda.id}, ${agenda.prueba_id})`
   393→                                    })
   394→                                    : (agenda.estado_id == "2")
   395→                                        ? crearBoton({
   396→                                            clases: 'btn-primary w-100 d-flex justify-content-center',
   397→                                            texto: 'Continuar',
   398→                                            onclick: `iniciarPruebaConDemograficas(${agenda.id}, ${agenda.prueba_id})`
   399→                                        })
   400→                                        : ''
   401→                            }
   402→                        </div>
   403→                    </div>
   404→                </div>
   405→            </div>
   406→        `;
   407→    });
   408→
   409→    return html;
   410→}
   411→
   412→/**
   413→ * Obtiene el texto del botón según el tipo de etapa
   414→ * 
   415→ * @param {string} nombre_etapa - Nombre de la etapa
   416→ * @returns {string} Texto del botón
   417→ * @author Andres Morales
   418→ */
   419→function obtenerTextoBotonEtapa(nombre_etapa) {
   420→    var nombre_normalizado = nombre_etapa
   421→        .toUpperCase()
   422→        .normalize('NFD')
   423→        .replace(/[\u0300-\u036f]/g, '')
   424→        .replace(/[^A-Z0-9]/g, '');
   425→
   426→    switch(nombre_normalizado) {
   427→        case 'PREGUNTASPREFILTRO':
   428→            return 'Responder';
   429→        case 'PRUEBATECNICA':
   430→            return 'Responder';
   431→        case 'DOCUMENTOSPARACONTRATACION':
   432→            return `<i class="bi bi-eye me-2"></i> Ver y adjuntar`;
   433→        case 'ENTREVISTA':
   434→            return 'Responder';
   435→        case 'REVISIONHV':
   436→            return 'Responder';
   437→        default:
   438→            return 'Responder';
   439→    }
   440→}
   441→
   442→/**
   443→ * Obtiene el valor de una configuración por su llave
   444→ * 
   445→ * @param {Array} configuraciones - Array de configuraciones
   446→ * @param {string} llave_buscar - Llave a buscar en movimiento_configuracion (puede ser parcial)
   447→ * @param {boolean} busqueda_parcial - Si es true, busca coincidencia parcial en la llave
   448→ * @returns {string|null} Valor de la configuración o null si no existe
   449→ * @author Andres Morales
   450→ */
   451→function obtenerConfiguracionPorLlave(configuraciones, llave_buscar, busqueda_parcial = false) {
   452→    if (!configuraciones || configuraciones.length === 0) return null;
   453→
   454→    var configuracion = configuraciones.find(config => {
   455→        var llave = config?.movimiento_configuracion?.llave;
   456→        if (!llave) return false;
   457→
   458→        return busqueda_parcial ? llave.includes(llave_buscar) : llave === llave_buscar;
   459→    });
   460→
