   464→/**
   465→ * Normaliza el nombre de una etapa removiendo espacios, acentos y caracteres especiales.
   466→ *
   467→ * @param {string} nombre - Nombre de la etapa a normalizar
   468→ * @returns {string} Nombre normalizado en mayúsculas sin espacios ni acentos
   469→ * @author Andres Morales
   470→ */
   471→function normalizarNombreEtapa(nombre) {
   472→    if (!nombre) return '';
   473→
   474→    return nombre
   475→        .toUpperCase()
   476→        .normalize('NFD')
   477→        .replace(/[\u0300-\u036f]/g, '')
   478→        .replace(/[^A-Z0-9]/g, '');
   479→}
