   878→function ejecutarAccionEtapaInterno(etapa_id, vacante_id) {
   879→    var vacante = datos_ids.find(elemento_vacante => elemento_vacante.id === vacante_id && elemento_vacante.hasOwnProperty('etapas'));
   880→
   881→    if (!vacante) {
   882→        mostrarToast('danger', 'No se encontró la vacante');
   883→        return;
   884→    }
   885→
   886→    var etapa = vacante.etapas.find(elemento_etapa => elemento_etapa.id === etapa_id);
   887→
   888→    if (!etapa) {
   889→        mostrarToast('danger', 'No se encontró la etapa');
   890→        return;
   891→    }
   892→
   893→    if (!etapa.usuarios_vacantes || etapa.usuarios_vacantes.length === 0) {
   894→        mostrarToast('danger', 'No tienes asignada esta etapa');
   895→        return;
   896→    }
   897→
   898→    var descripcion_prueba = obtenerConfiguracionPorLlave(etapa.configuraciones, 'descripcion_prueba_tecnica');
   899→    var fecha_vencimiento = etapa.usuarios_vacantes[0].fecha_vencimiento;
   900→
   901→    var documentos_solicitados_config = obtenerConfiguracionPorLlave(etapa.configuraciones, 'documentos_solicitados');
   902→    var documentos_solicitados = [];
   903→
   904→    if (documentos_solicitados_config) {
   905→        try {
   906→            documentos_solicitados = JSON.parse(documentos_solicitados_config);
   907→        } catch (e) {
   908→            console.error('Error al parsear documentos solicitados:', e);
   909→        }
   910→    }
   911→
   912→    var datos_etapa = {
   913→        id: etapa.id,
   914→        nombre: etapa.nombre,
   915→        etapa_vacante_usuario_id: etapa.usuarios_vacantes[0].id,
   916→        archivos: etapa.archivos || [],
   917→        vacante_nombre: vacante.nombre_vacante,
   918→        vacante_id: vacante.id,
   919→        descripcion: descripcion_prueba,
   920→        fecha_cierre: fecha_vencimiento,
   921→        documentos_solicitados: documentos_solicitados,
   922→        configuracion_ia_hv : obtenerConfiguracionPorLlave(etapa.configuraciones, 'revision_hv_ia'),
   923→        prueba_tecnica: etapa.usuarios_vacantes[0].pruebas_tecnicas && etapa.usuarios_vacantes[0].pruebas_tecnicas.length > 0
   924→            ? etapa.usuarios_vacantes[0].pruebas_tecnicas[0]
   925→            : null
   926→    };
   927→
   928→    var nombre_normalizado = normalizarNombreEtapa(etapa.nombre);
   929→
   930→    switch(nombre_normalizado) {
   931→        case 'VIDEOENTREVISTA':
