  1251→/**
  1252→ * Verifica si hay tareas pendientes en los datos cargados.
  1253→ * Analiza todas las etapas posibles para determinar si hay trabajo por hacer.
  1254→ *
  1255→ * @param {Array} vacantes - Array de vacantes/procesos cargados
  1256→ * @returns {boolean} true si hay tareas pendientes, false si no
  1257→ * @author Jair Carvajal
  1258→ */
  1259→function verificarTareasPendientesEnDatos(vacantes) {
  1260→    if (!vacantes || vacantes.length === 0) {
  1261→        return false;
  1262→    }
  1263→
  1264→    let tiene_tareas_pendientes = false;
  1265→
  1266→    vacantes.forEach(function(vacante) {
  1267→        if (tiene_tareas_pendientes) return;
  1268→
  1269→        if (vacante.vacante_id === null || vacante.agendas !== undefined) {
  1270→            if (vacante.agendas && vacante.agendas.length > 0) {
  1271→                vacante.agendas.forEach(function(agenda) {
  1272→                    if (agenda.estado_id == '1' || agenda.estado_id == '2') {
  1273→                        tiene_tareas_pendientes = true;
  1274→                    }
  1275→                });
  1276→            }
  1277→            return;
  1278→        }
  1279→
  1280→        if (vacante.etapas && vacante.etapas.length > 0) {
  1281→            vacante.etapas.forEach(function(etapa) {
  1282→                if (tiene_tareas_pendientes) return;
  1283→
  1284→                let nombre_normalizado = normalizarNombreEtapa(etapa.nombre);
  1285→                if (nombre_normalizado === 'PRUEBASPSICOMETRICAS') {
  1286→                    if (etapa.agendas && etapa.agendas.length > 0) {
  1287→                        etapa.agendas.forEach(function(agenda) {
  1288→                            if (agenda.estado_id == '1' || agenda.estado_id == '2') {
  1289→                                tiene_tareas_pendientes = true;
  1290→                            }
  1291→                        });
  1292→                    }
  1293→                    return;
  1294→                }
  1295→
  1296→                // Verificar videoentrevista
  1297→                if (nombre_normalizado === 'VIDEOENTREVISTA' && etapa.activa == 1) {
  1298→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1299→                        let usuario_vacante = etapa.usuarios_vacantes[0];
  1300→
  1301→                        // Verificar si la videoentrevista está completa
  1302→                        if (usuario_vacante.etapa_video_entrevista_completa != true) {
  1303→                            tiene_tareas_pendientes = true;
  1304→                        }
  1305→
  1306→                        // Verificar formato de videoentrevista si está configurado
  1307→                        let solicita_formato = obtenerConfiguracionPorLlave(etapa.configuraciones, 'solicitar_formato_videoentrevista');
  1308→                        if (solicita_formato == '1') {
  1309→                            let formato_entrevista = usuario_vacante.formato_entrevista;
  1310→                            if (!formato_entrevista || formato_entrevista.descripcion_vacante === null) {
  1311→                                tiene_tareas_pendientes = true;
  1312→                            }
  1313→                        }
  1314→                    }
  1315→                    return;
  1316→                }
  1317→
  1318→                // Verificar preguntas prefiltro
  1319→                if (nombre_normalizado === 'PREGUNTASPREFILTRO' && etapa.activa == 1) {
  1320→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1321→                        tiene_tareas_pendientes = true;
  1322→                    }
  1323→                    return;
  1324→                }
  1325→
  1326→                // Verificar prueba técnica
  1327→                if (nombre_normalizado === 'PRUEBATECNICA' && etapa.activa == 1) {
  1328→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1329→                        let usuario_vacante = etapa.usuarios_vacantes[0];
  1330→                        let pruebas_tecnicas = usuario_vacante.pruebas_tecnicas;
  1331→
  1332→                        // Pendiente si no hay prueba técnica o está en borrador
  1333→                        if (!pruebas_tecnicas || pruebas_tecnicas.length === 0 || pruebas_tecnicas[0].borrador == 1) {
  1334→                            tiene_tareas_pendientes = true;
  1335→                        }
  1336→                    }
  1337→                    return;
  1338→                }
  1339→
  1340→                // Verificar documentos para contratación
  1341→                if (nombre_normalizado === 'DOCUMENTOSPARACONTRATACION' && etapa.activa == 1) {
  1342→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1343→                        tiene_tareas_pendientes = true;
  1344→                    }
  1345→                    return;
  1346→                }
  1347→
  1348→                // Verificar entrevista (formato de entrevista)
  1349→                if (nombre_normalizado === 'ENTREVISTA' && etapa.activa == 1) {
  1350→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1351→                        let usuario_vacante = etapa.usuarios_vacantes[0];
  1352→                        let formato_entrevista = usuario_vacante.formato_entrevista;
  1353→
  1354→                        // Pendiente si no hay formato de entrevista o está vacío
  1355→                        if (!formato_entrevista || formato_entrevista.descripcion_vacante === null) {
  1356→                            tiene_tareas_pendientes = true;
  1357→                        }
  1358→                    }
  1359→                    return;
  1360→                }
  1361→
  1362→                // Verificar revisión HV
  1363→                if (nombre_normalizado === 'REVISIONHV' && etapa.activa == 1) {
  1364→                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1365→                        tiene_tareas_pendientes = true;
  1366→                    }
  1367→                    return;
  1368→                }
  1369→
  1370→                // Verificar otras etapas activas con usuarios asignados
  1371→                if (etapa.activa == 1 && etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
  1372→                    tiene_tareas_pendientes = true;
  1373→                }
  1374→            });
  1375→        }
  1376→    });
  1377→
  1378→    return tiene_tareas_pendientes;
  1379→}
