var datos_ids = [];
var validacion_inicial_realizada = false;

$(`#tabla-tareas-pendientes`).DataTable({
    ...configuracion_tablas,
    ajax: {
        url : `/vacantes-aplicante`,
        data: function (datos) {
            ($('#filtro_estado_tarea').val() != 0 ) ? datos.estado_id = $('#filtro_estado_tarea').val() : '';
            ($('#filtro_tipo_prueba').val()) ? datos.tipo_prueba_id = $('#filtro_tipo_prueba').val() : '';
            if (typeof $('#fecha_filtro').val() === 'string') {
                let partes_fecha = $('#fecha_filtro').val().split(' a ');
                (partes_fecha[0]) ? datos.fecha_inicio = partes_fecha[0] : '';
                (partes_fecha[1]) ? datos.fecha_cierre = partes_fecha[1] : '';
            }
        },
        dataSrc: function (json) {
            return Object.values(json.data);
        }
    },
    columns: [
        {
            data: null,
            orderable : false,
            class: 'p-1 rounded-3',
            render: (dato) => {
                let es_proceso = dato.vacante_id === null || dato.agendas !== undefined;

                if (es_proceso) {
                    return renderizarProceso(dato);
                } else {
                    return renderizarVacante(dato);
                }
            }
        }
    ],
    drawCallback: function() {
        datos_ids = $('#tabla-tareas-pendientes').DataTable().data().toArray();
        inicializarTooltips();
        validarDatos();
        abrirAcordeonVacante();
    },
    initComplete: function() {
        datos_ids = $('#tabla-tareas-pendientes').DataTable().data().toArray();
        $('[aria-describedby="tabla-tareas-pendientes_info"] .thead-componente').hide();
        inicializarTooltips();
        validarDatos();
        abrirAcordeonVacante();

        if (!validacion_inicial_realizada) {
            validacion_inicial_realizada = true;
            verificarYRedirigirSiNoHayTareasPendientes();
        }
    }
}); 

$(document).ready(function() {
