});

/**
 * Muestra u oculta tablas según la existencia de datos.
 *
 * @returns {void}
 * @author Andres Morales
 */
function validarDatos() {
    var tiene_filtros_aplicados = verificarFiltrosAplicados();

    if (datos_ids.length == 0) {
        if (tiene_filtros_aplicados) {
            // Si hay filtros aplicados, mostrar los controles pero con empty state en la tabla
            $('#tabla-contenido').removeClass('d-none');
            $('#tabla-sin-contenido').addClass('d-none');
            mostrarEstadoVacioFiltros();
        } else {
            // Si no hay filtros, ocultar todo y mostrar el empty state general
            $('#tabla-contenido').addClass('d-none');
            $('#tabla-sin-contenido').removeClass('d-none');
        }
    } else {
        $('#tabla-contenido').removeClass('d-none');
        $('#tabla-sin-contenido').addClass('d-none');
        ocultarEstadoVacioFiltros();
    }
}

/**
 * Verifica si hay filtros aplicados en la tabla.
 *
 * @returns {boolean}
 * @author Andres Morales
 */
function verificarFiltrosAplicados() {
    var valor_filtro_estado = $('#filtro_estado_tarea').val();
    var valor_filtro_fecha = $('#filtro_fecha').val();
    var valor_buscador = $('.dt-search input').val();

    return (valor_filtro_estado && valor_filtro_estado != '0') ||
           (valor_filtro_fecha && valor_filtro_fecha.trim() !== '') ||
           (valor_buscador && valor_buscador.trim() !== '');
}

/**
 * Muestra el empty state cuando hay filtros aplicados pero no hay resultados.
 *
 * @returns {void}
 * @author Andres Morales
 */
function mostrarEstadoVacioFiltros() {
    var contenedor_tabla = $('#tabla-tareas-pendientes_wrapper');

    if (contenedor_tabla.find('.estado-vacio-filtros').length === 0) {
        var html_estado_vacio = `
            <div class="estado-vacio-filtros w-100 text-center p-10">
                <p class=""><i class="bi bi-funnel text-gray-60 icono-estado-vacio"></i></p>
                <p class="pb-4 text-headline-5 fw-bold text-gray-30">No se encontraron resultados con los filtros aplicados.</p>
            </div>
        `;
        contenedor_tabla.find('table').hide();
        contenedor_tabla.append(html_estado_vacio);
    }
}

/**
 * Oculta el empty state de filtros cuando hay resultados.
 *
 * @returns {void}
 * @author Andres Morales
 */
function ocultarEstadoVacioFiltros() {
    var contenedor_tabla = $('#tabla-tareas-pendientes_wrapper');
    contenedor_tabla.find('.estado-vacio-filtros').remove();
    contenedor_tabla.find('table').show();
}

