/**
 * Renderiza una tarjeta para una vacante con etapas.
 *
 * @param {Object} dato - Objeto de vacante con etapas.
 * @returns {string} HTML generado con la estructura de la tarjeta de la vacante.
 * @author Andres Morales
 * @author Andres Gonzalez
 * @author José Manuel Jiménez
 */
function renderizarVacante(dato) {
    let es_primera_columna = false;
    let clase_boton = es_primera_columna ? 'accordion-button shadow-none text-body-1' : 'accordion-button shadow-none text-body-1 collapsed';
    let area_expandida = es_primera_columna ? 'true' : 'false';
    let clase_para_colapsado = es_primera_columna ? 'accordion-collapse collapse show' : 'accordion-collapse collapse';
    let mostrar_empresa = dato?.empresa !== null && dato?.empresa !== undefined;

    let etapa_actual = dato.etapa_actual || 0;
    let total_etapas = dato.total_etapas || 0;
    let porcentaje_progreso = (etapa_actual / total_etapas) * 100;

    let total_agendas = 0;
    let total_etapas_activas = 0;

    if (dato?.etapas && dato.etapas.length > 0) {
        dato.etapas.forEach((etapa) => {
            var nombre_normalizado = normalizarNombreEtapa(etapa.nombre);
            if (nombre_normalizado === 'PRUEBASPSICOMETRICAS' && etapa.agendas && etapa.agendas.length > 0) {
                total_agendas += etapa.agendas.length;
            } else if (nombre_normalizado !== 'PRUEBASPSICOMETRICAS' && etapa.activa == 1) {
                if (nombre_normalizado === 'VIDEOENTREVISTA') {
                    if (etapa.usuarios_vacantes[0].etapa_video_entrevista_completa != true) {
                        total_etapas_activas++;
                    }
                    let solicita_formato = obtenerConfiguracionPorLlave(etapa.configuraciones, 'solicitar_formato_videoentrevista');
                    if (solicita_formato == '1') {
                        let formato_entrevista = etapa.usuarios_vacantes[0].formato_entrevista;
                        let completo_formato_entrevista = formato_entrevista && formato_entrevista.descripcion_vacante !== null;
                        if (completo_formato_entrevista == null) {
                            total_etapas_activas++;
                        }
                    }
                } else {
                    total_etapas_activas++;
                }
            } else {
                total_etapas_activas++;
            }
        });
    }

    let total_tareas_alerta = total_agendas > 0 ? total_agendas : total_etapas_activas;

    let titulo_tareas = total_agendas > 0
        ? `Pruebas psicométricas (${total_agendas})`
        : `Tareas de selección (${total_etapas_activas})`;

    let empresa_html = mostrar_empresa ? `
        <div class="col-12 d-flex">
            <i class="my-auto bi bi-buildings-fill text-body-3 text-gray-30"></i>
            <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">Empresa:</h5>
            <img class="my-auto border rounded" width="24px" height="24px" src="/empresas-logo/${dato?.empresa_id}" alt="${dato?.empresa?.nombre_comercial}" onerror="this.onerror=null;"/>
            <h5 class="my-auto card-title text-body-3 text-gray-30 mx-2">${dato?.empresa?.nombre_comercial}</h5>
        </div>
    ` : '';

    let barra_progreso_html = `
        <div class="col-12 mt-3">
            ${crearProgressBar({
                label: '<span class="text-body-3 fw-bolder mb-3"><i class="bi bi-bar-chart-steps me-2"></i>Etapa actual: ' + etapa_actual + ' de ' + total_etapas + '</span>',
                height: '8px',
                class_label: 'mb-1',
                porcentaje: {
                    porcentaje: porcentaje_progreso,
                    texto: false
                },
                class: 'barra-progreso-etapa',
                rounded: 'rounded-3',
                rounded2: 'rounded-3'
            })}
        </div>
    `;

    return `
        <div class="card">
            <div class="card-body">
                <div class="row mb-3">
                    <div class="col-12">
                        <h5 class="card-title text-body-1 fw-bolder text-gray-10">${dato.nombre_vacante}</h5>
                    </div>
                    ${empresa_html}
                    ${barra_progreso_html}
                </div>
                <div class="accordion" id="accordionVacante${dato?.id}">
                    <div class="accordion-item">
                        <h2 class="accordion-header">
                            <button class="${clase_boton} d-flex justify-content-between align-items-center" type="button" data-bs-toggle="collapse" data-bs-target="#collapseVacante${dato.id}" aria-expanded="${area_expandida}" aria-controls="collapseVacante${dato.id}">
                                <span>Ver tareas pendientes</span>
                                ${total_tareas_alerta > 0 ? `<span class="badge bg-danger rounded-pill text-label-2">${total_tareas_alerta}</span>` : ''}
                            </button>
                        </h2>
                        <div id="collapseVacante${dato.id}" class="${clase_para_colapsado}" data-bs-parent="#accordionVacante${dato?.id}">
                            <div class="accordion-body">
                                ${total_tareas_alerta > 0 ? `<h1 class="text-headline-5 fw-bloder text-gray-10">${titulo_tareas}</h1>` : ''}
