    `;
}

/**
 * Genera el HTML para mostrar una lista de agendas en tarjetas (cards) con su información detallada.
 *
 * @param {Array<Object>} agendas - Arreglo de objetos de agenda a procesar.
 * @returns {string} HTML generado con la estructura de las tarjetas para cada agenda.
 * @author Andres Morales
 * @author Fahibram Cárcamo
 * @author Andres Gonzalez
 */
function procesarAgendas(agendas) {
    let estado_clases = {
        '1': 'tag-filled-yellow',
        '2': 'tag-filled-blue',
        '3': 'tag-filled-green',
        '4': 'tag-filled-red',
        '5': 'tag-filled-gray',
        '6': 'tag-filled-green'
    };
    let html = '';

    if (!agendas || agendas.length === 0) {
        return '<div class="col-12"><p class="text-center text-gray-30">No hay pruebas asignadas</p></div>';
    }

    let orden_estado = [2, 1, 3, 4];

    agendas.sort((a, b) => {
        let primer_estado = orden_estado.indexOf(Number(a.estado_id));
        let segundo_estado = orden_estado.indexOf(Number(b.estado_id));
        return (primer_estado === -1 ? orden_estado.length : primer_estado) - (segundo_estado === -1 ? orden_estado.length : segundo_estado);
    });

    agendas.forEach((agenda) => {
        if (agenda.estado.nombre == 'Agendada') agenda.estado.nombre = 'Pendiente';
        else if (agenda.estado.nombre == 'Sin pago') agenda.estado.nombre = 'Finalizada';

        html += `
            <div class="col p-0 columna-tarjeta-tarea">
                <div class="card h-100">
                    <div class="card-body d-flex flex-column cuerpo-tarjeta-tarea">
                        <div class="w-100 d-flex flex-column row-gap-3">
                            <div class="w-100 d-flex justify-content-between align-items-center">
                                <h5 class="card-title text-headline-5 text-gray-10 fw-medium fw-bold m-0">${agenda?.prueba?.nombre ?? ''}</h5>
                                <div class="d-flex flex-row">
                                    ${
                                        (estado_clases[agenda.estado_id])
                                            ? crearTag({
                                                texto: agenda?.estado?.nombre ?? '',
                                                class: estado_clases[agenda.estado_id]
                                            })
                                            : ''
                                    }
                                    ${
                                        (agenda?.estado_id == "4")
                                            ? `<i
                                                class="bi bi-info-circle-fill text-info ms-3 text-headline-3 pointer"
                                                ${crearTooltip({
                                                    placement: `top`,
                                                    content: `Esta tarea ha expirado debido a que se ha superado el tiempo límite de entrega.`,
                                                    toggle: `popover`
                                                })}
                                            ></i>`
                                            : ''
                                    }
                                </div>
                            </div>

                            <div class="w-100 d-flex flex-column row-gap-2">
                                <div class="w-100 d-flex justify-content-start">
                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-clock me-2"></i>Tiempo estimo:&nbsp;${agenda?.prueba?.duracion ?? '0'}&nbsp;minutos</p>
                                </div>
                                <div class="w-100 d-flex justify-content-start">
                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-circle-fill text-green-cta me-2"></i>Asignada:&nbsp;${formatearFecha(agenda?.fecha_inicio)}</p>
                                </div>
                                <div class="w-100 d-flex justify-content-start">
                                    <p class="text-label-2 text-gray-30 mb-0"><i class="bi bi-circle-fill text-red-cta me-2"></i>Expira:&nbsp;${formatearFecha(agenda?.fecha_cierre)}</p>
                                </div>
                            </div>
                        </div>

                        <div class="w-100">
                            ${
                                (agenda.estado_id == "1")
                                    ? crearBoton({
                                        clases: 'btn-primary w-100 d-flex justify-content-center',
                                        texto: 'Responder',
                                        onclick: `iniciarPruebaConDemograficas(${agenda.id}, ${agenda.prueba_id})`
                                    })
                                    : (agenda.estado_id == "2")
                                        ? crearBoton({
                                            clases: 'btn-primary w-100 d-flex justify-content-center',
                                            texto: 'Continuar',
                                            onclick: `iniciarPruebaConDemograficas(${agenda.id}, ${agenda.prueba_id})`
                                        })
                                        : ''
                            }
                        </div>
                    </div>
                </div>
            </div>
        `;
    });

    return html;
}

/**
 * Obtiene el texto del botón según el tipo de etapa
 * 
 * @param {string} nombre_etapa - Nombre de la etapa
 * @returns {string} Texto del botón
 * @author Andres Morales
 */
function obtenerTextoBotonEtapa(nombre_etapa) {
    var nombre_normalizado = nombre_etapa
        .toUpperCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^A-Z0-9]/g, '');

    switch(nombre_normalizado) {
        case 'PREGUNTASPREFILTRO':
            return 'Responder';
        case 'PRUEBATECNICA':
            return 'Responder';
        case 'DOCUMENTOSPARACONTRATACION':
            return `<i class="bi bi-eye me-2"></i> Ver y adjuntar`;
        case 'ENTREVISTA':
            return 'Responder';
        case 'REVISIONHV':
            return 'Responder';
        default:
            return 'Responder';
    }
}

/**
 * Obtiene el valor de una configuración por su llave
 * 
 * @param {Array} configuraciones - Array de configuraciones
 * @param {string} llave_buscar - Llave a buscar en movimiento_configuracion (puede ser parcial)
 * @param {boolean} busqueda_parcial - Si es true, busca coincidencia parcial en la llave
 * @returns {string|null} Valor de la configuración o null si no existe
 * @author Andres Morales
 */
function obtenerConfiguracionPorLlave(configuraciones, llave_buscar, busqueda_parcial = false) {
    if (!configuraciones || configuraciones.length === 0) return null;

    var configuracion = configuraciones.find(config => {
        var llave = config?.movimiento_configuracion?.llave;
        if (!llave) return false;

        return busqueda_parcial ? llave.includes(llave_buscar) : llave === llave_buscar;
    });

    return configuracion?.valor ?? null;
}

/**
 * Normaliza el nombre de una etapa removiendo espacios, acentos y caracteres especiales.
 *
 * @param {string} nombre - Nombre de la etapa a normalizar
 * @returns {string} Nombre normalizado en mayúsculas sin espacios ni acentos
 * @author Andres Morales
 */
function normalizarNombreEtapa(nombre) {
    if (!nombre) return '';

    return nombre
        .toUpperCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^A-Z0-9]/g, '');
}

/**
 * Genera el HTML para mostrar una lista de etapas en tarjetas (cards) con su información detallada.
 *
 * @param {Array<Object>} etapas - Arreglo de objetos de etapas a procesar.
 * @param {number} vacante_id - ID de la vacante a la que pertenecen las etapas.
 * @returns {string} HTML generado con la estructura de las tarjetas para cada etapa.
 * @author Andres Morales
 * @author Fahibram Cárcamo
 * @author Andres Gonzalez
 */
function procesarEtapas(etapas, vacante_id) {
    let html = '';

    if (!etapas || etapas.length === 0) {
        return '<div class="col-12"><p class="text-center text-gray-30">No hay tareas pendientes</p></div>';
    }

    let etapas_ordenadas = [...etapas].sort((a, b) => a.orden - b.orden);

    etapas_ordenadas.forEach((etapa) => {
        // Si la etapa es "Pruebas psicométricas" y tiene agendas, mostrarlas en lugar de la etapa
        var nombre_normalizado = normalizarNombreEtapa(etapa.nombre);

        if (nombre_normalizado === 'PRUEBASPSICOMETRICAS' && etapa.agendas && etapa.agendas.length > 0) {
            html += procesarAgendas(etapa.agendas);
            return;
        }

        // Si la etapa es "Videoentrevista" y tiene formato de entrevista configurado, mostrar ambas cards
        if (nombre_normalizado === 'VIDEOENTREVISTA') {
            let solicita_formato = obtenerConfiguracionPorLlave(etapa.configuraciones, 'solicitar_formato_videoentrevista');

            if (solicita_formato === '1') {
                html += generarContenedorFormatoEntrevista(etapa, vacante_id);
                html += generarCardVideoentrevista(etapa, vacante_id);
                return;
            }
        }

        let esta_activa = etapa.activa == 1;
        let tiene_tareas = etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0;

        let clase_etiqueta = esta_activa ? 'tag-filled-blue' : 'tag-filled-yellow';
        let texto_estado = esta_activa ? 'Iniciada' : 'Pendiente';
        let $tiempo_prueba = Math.round((etapa.duracion ?? 300) / 60);
        let nombre_etapa = etapa.nombre || '';

        if (nombre_normalizado === 'PRUEBATECNICA' && etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
            let pruebas_tecnicas = etapa.usuarios_vacantes[0].pruebas_tecnicas;
            if (pruebas_tecnicas && pruebas_tecnicas.length > 0) {
                let es_borrador = pruebas_tecnicas[0].borrador == 1;
                clase_etiqueta = es_borrador ? 'tag-filled-blue' : 'tag-filled-yellow';
                texto_estado = es_borrador ? 'Iniciada' : 'Pendiente';
            } else {
                let es_borrador = false;
                clase_etiqueta = es_borrador ? 'tag-filled-blue' : 'tag-filled-yellow';
                texto_estado = es_borrador ? 'Iniciada' : 'Pendiente';
            }
        }

        if (nombre_normalizado === 'DOCUMENTOSPARACONTRATACION' && etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
            let archivos = etapa.usuarios_vacantes[0].archivos || [];
            let archivos_aplicante = archivos.filter(archivo => !archivo.nombre.startsWith('cliente_empresa_'));
            let tiene_archivos = archivos_aplicante.length > 0;
            clase_etiqueta = tiene_archivos ? 'tag-filled-blue' : 'tag-filled-yellow';
            texto_estado = tiene_archivos ? 'Iniciada' : 'Pendiente';
        }

        if (nombre_normalizado === 'PREGUNTASPREFILTRO') {
            clase_etiqueta = 'tag-filled-yellow';
            texto_estado = 'Pendiente';
        }

        if (nombre_normalizado === 'REVISIONHV') {
            clase_etiqueta = 'tag-filled-yellow';
            texto_estado = 'Pendiente';
        }

        if (nombre_normalizado === 'VIDEOENTREVISTA') {
            clase_etiqueta = 'tag-filled-yellow';
            texto_estado = 'Pendiente';
        }

        if (nombre_normalizado === 'ENTREVISTA') {
            $tiempo_prueba = 15
            let formato_entrevista       = etapa.usuarios_vacantes[0].formato_entrevista;
            let tiene_formato_entrevista = formato_entrevista && formato_entrevista.descripcion_vacante !== null;
            clase_etiqueta               = tiene_formato_entrevista ? 'tag-filled-blue' : 'tag-filled-yellow';
            texto_estado                 = tiene_formato_entrevista ? 'Iniciada' : 'Pendiente';
            nombre_etapa                 = 'Formato de entrevista';
        }

        let fecha_notificacion = etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0
            ? etapa.usuarios_vacantes[0].fecha_notificacion
            : null;

        let fecha_vencimiento = etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0
            ? etapa.usuarios_vacantes[0].fecha_vencimiento
            : null;

        let es_documentos_solicitados = nombre_normalizado === 'DOCUMENTOSPARACONTRATACION';
        let ocultar_tiempo_estimado = ['REVISIONHV', 'PRUEBATECNICA', 'DOCUMENTOSPARACONTRATACION'].includes(nombre_normalizado);

        html += `
