/**
 * Valida si el usuario tiene la información básica completada.
 * Si no la tiene, muestra el modal de información incompleta.
 *
 * @returns {Promise<boolean>} true si la información está completa, false si no
 * @author Andres Morales
 */
function validarInformacionBasicaUsuario() {
    return new Promise((resolucion, rechazo) => {
        $.ajax({
            url: '/usuario-validar-informacion-basica',
            type: 'GET',
            success: function(respuesta) {
                if (respuesta.data.informacion_completa) {
                    resolucion(true);
                } else {
                    // Guardar el usuario_id para usarlo después
                    window.usuario_id_actual = respuesta.data.usuario_id;
                    $('#modal-informacion-incompleta').modal('show');
                    resolucion(false);
                }
            },
            error: function(respuesta_xhr) {
                mostrarToast('danger', 'Error al validar la información. Intenta nuevamente.');
                rechazo(false);
            }
        });
    });
}

/**
 * Cierra el modal de información incompleta.
 *
 * @returns {void}
 * @author Andres Morales
 */
function cerrarModalInformacionIncompleta() {
    $('#modal-informacion-incompleta').modal('hide');
}

/**
 * Redirige al usuario a la página de editar perfil.
 *
 * @returns {void}
 * @author Andres Morales
 */
function irEditarPerfil() {
    var usuario_id = window.usuario_id_actual || '';
    if (usuario_id) {
        window.location.href = `/usuarios/${usuario_id}/edit`;
    } else {
        mostrarToast('danger', 'No se pudo obtener el ID del usuario.');
    }
}

/**
 * Ejecuta la acción correspondiente según el tipo de etapa de la vacante.
 * Valida la existencia de la vacante y etapa, y delega a la función específica.
 *
 * @param {number} etapa_id - ID de la etapa a ejecutar
 * @param {number} vacante_id - ID de la vacante asociada
 * @returns {void}
 * @author Andres Morales
 * @author Andres Gonzalez
 */
function ejecutarAccionEtapa(etapa_id, vacante_id) {
    // Primero validar la información básica del usuario
    validarInformacionBasicaUsuario().then(function(informacion_completa) {
        if (!informacion_completa) {
            return;
        }

        // Si la información está completa, continuar con la lógica original
        ejecutarAccionEtapaInterno(etapa_id, vacante_id);
    });
}

/**
 * Función interna que ejecuta la acción de la etapa sin validación previa.
 *
 * @param {number} etapa_id - ID de la etapa a ejecutar
 * @param {number} vacante_id - ID de la vacante asociada
 * @returns {void}
 * @author Andres Morales
 * @author Andres Gonzalez
 */
function ejecutarAccionEtapaInterno(etapa_id, vacante_id) {
    var vacante = datos_ids.find(elemento_vacante => elemento_vacante.id === vacante_id && elemento_vacante.hasOwnProperty('etapas'));

    if (!vacante) {
        mostrarToast('danger', 'No se encontró la vacante');
        return;
    }

    var etapa = vacante.etapas.find(elemento_etapa => elemento_etapa.id === etapa_id);

    if (!etapa) {
        mostrarToast('danger', 'No se encontró la etapa');
        return;
    }

    if (!etapa.usuarios_vacantes || etapa.usuarios_vacantes.length === 0) {
        mostrarToast('danger', 'No tienes asignada esta etapa');
        return;
    }

    var descripcion_prueba = obtenerConfiguracionPorLlave(etapa.configuraciones, 'descripcion_prueba_tecnica');
    var fecha_vencimiento = etapa.usuarios_vacantes[0].fecha_vencimiento;

    var documentos_solicitados_config = obtenerConfiguracionPorLlave(etapa.configuraciones, 'documentos_solicitados');
    var documentos_solicitados = [];

    if (documentos_solicitados_config) {
        try {
            documentos_solicitados = JSON.parse(documentos_solicitados_config);
        } catch (e) {
            console.error('Error al parsear documentos solicitados:', e);
        }
    }

    var datos_etapa = {
        id: etapa.id,
        nombre: etapa.nombre,
        etapa_vacante_usuario_id: etapa.usuarios_vacantes[0].id,
        archivos: etapa.archivos || [],
        vacante_nombre: vacante.nombre_vacante,
        vacante_id: vacante.id,
        descripcion: descripcion_prueba,
        fecha_cierre: fecha_vencimiento,
        documentos_solicitados: documentos_solicitados,
        configuracion_ia_hv : obtenerConfiguracionPorLlave(etapa.configuraciones, 'revision_hv_ia'),
        prueba_tecnica: etapa.usuarios_vacantes[0].pruebas_tecnicas && etapa.usuarios_vacantes[0].pruebas_tecnicas.length > 0
            ? etapa.usuarios_vacantes[0].pruebas_tecnicas[0]
            : null
    };

    var nombre_normalizado = normalizarNombreEtapa(etapa.nombre);

    switch(nombre_normalizado) {
        case 'VIDEOENTREVISTA':
            window.location.href = `/bienvenida-preguntas-videoentrevista?etapa_vacante_id=${datos_etapa.id}`;
            break;

        case 'PREGUNTASPREFILTRO':
            window.location.href = `/bienvenida-preguntas-prefiltro?etapa_vacante_id=${datos_etapa.id}`;
            break;

        case 'PRUEBATECNICA':
            abrirModalPruebaTecnica(datos_etapa);
            break;

        case 'DOCUMENTOSPARACONTRATACION':
            abrirModalDocumentosSolicitados(datos_etapa);
            break;

        case 'ENTREVISTA':
            window.location.href = `/formatos-entrevistas/create?etapa_vacante_usuario_id=${datos_etapa.etapa_vacante_usuario_id}`;
            break;

        case 'REVISIONHV':
            limpiarFormularioRevisionHV();
            abrirModalRevisionHV(datos_etapa);
            break;

        default:
            mostrarToast('info', 'No hay acciones disponibles para esta etapa');
            break;
    }
}

/**
 * Ejecuta la acción de videoentrevista directamente sin validación de información básica.
 *
 * @param {number} etapa_id - ID de la etapa a ejecutar
 * @param {number} vacante_id - ID de la vacante asociada
 * @returns {void}
 * @author Andres Morales
 */
function ejecutarAccionVideoentrevista(etapa_id, vacante_id) {
    validarInformacionBasicaUsuario().then(function(informacion_completa) {
        if (!informacion_completa) {
            return;
        }
        window.location.href = `/bienvenida-preguntas-videoentrevista?etapa_vacante_id=${etapa_id}`;
    });
}

/**
 * Ejecuta la acción para abrir el formato de entrevista cuando es parte de videoentrevista.
 *
 * @param {number} etapa_id - ID de la etapa a ejecutar
 * @param {number} vacante_id - ID de la vacante asociada
 * @returns {void}
 * @author Andres Morales
 */
function ejecutarAccionFormatoEntrevista(etapa_id, vacante_id) {
    validarInformacionBasicaUsuario().then(function(informacion_completa) {
        if (!informacion_completa) {
            return;
        }

        var vacante = datos_ids.find(elemento_vacante => elemento_vacante.id === vacante_id && elemento_vacante.hasOwnProperty('etapas'));

        if (!vacante) {
            mostrarToast('danger', 'No se encontró la vacante');
            return;
        }

        var etapa = vacante.etapas.find(elemento_etapa => elemento_etapa.id === etapa_id);

        if (!etapa) {
            mostrarToast('danger', 'No se encontró la etapa');
            return;
        }

        if (!etapa.usuarios_vacantes || etapa.usuarios_vacantes.length === 0) {
            mostrarToast('danger', 'No tienes asignada esta etapa');
            return;
        }

        var etapa_vacante_usuario_id = etapa.usuarios_vacantes[0].id;
        window.location.href = `/formatos-entrevistas/create?etapa_vacante_usuario_id=${etapa_vacante_usuario_id}`;
    });
}

/**
 * Inicia la prueba verificando primero si hay demográficas pendientes.
 * Si hay demográficas, abre el modal; si no, redirige directamente a la prueba.
 *
 * @param {number} agenda_id - ID de la agenda
 * @param {number} prueba_id - ID de la prueba
 * @returns {void}
 * @author Andres Morales
 */
function iniciarPruebaConDemograficas(agenda_id, prueba_id) {
    $.ajax({
        url: `/demograficas-ajax/${agenda_id}/${prueba_id}`,
        type: 'GET',
        success: function(respuesta) {
            if (respuesta.data.redirigir_directo) {
                // No hay demográficas o ya están completas
                window.location.href = `/realizar-prueba/${agenda_id}`;
            } else {
                // Hay demográficas pendientes, abrir modal
                abrirModalDemograficas(respuesta.data);
            }
        },
        error: function(respuesta_xhr) {
            mostrarToast('danger', 'Error al cargar las demográficas. Intenta nuevamente.');
        }
    });
}

/**
 * Abre el modal de demográficas y renderiza el formulario dinámicamente.
 *
 * @param {Object} datos - Objeto con datos de demográficas y agenda
 * @returns {void}
 * @author Andres Morales
 */
function abrirModalDemograficas(datos) {
    // Establecer datos en campos ocultos
    $('#agenda_id_modal').val(datos.agenda_id);

    // Actualizar título del modal con el nombre de la prueba
    $('#titulo-modal-demograficas').text(`Datos demográficos - ${datos.agenda?.prueba?.nombre || 'Prueba'}`);

    // Limpiar contenedor
    $('#contenedor-demograficas-modal').empty();

    // Renderizar cada demográfica
    datos.demograficas.forEach(function(demografica) {
        let html_demografica = '';
        let elemento_id = "";
        if (!demografica.otro) {
            // Pregunta tipo select
            elemento_id = `demografica_${demografica.id}`
            html_demografica = `
                <div class="col-12 mb-4">
                    ${crearSelect2({
                        id: `${elemento_id}`,
                        name: `${elemento_id}`,
                        label: demografica.nombre,
                        required: true,
                        opciones: demografica.opciones.map(opcion => ({
                            id: opcion.id,
                            nombre: opcion.contenido
                        })),
                        buscador: true
                    })}
                </div>
            `;
        } else {
            // Pregunta tipo texto
            html_demografica = `
                <div class="col-12">
                    ${crearInput({
                        id: `demografica_opcion_${demografica.opciones[0].id}`,
                        name: `demografica_opcion_${demografica.opciones[0].id}`,
                        type: 'text',
                        label: demografica.nombre,
                        required: true,
                        autocomplete: 'off',
                        maxlength: 200
                    })}
                </div>
            `;
        }

        $('#contenedor-demograficas-modal').append(html_demografica);
        // Inicializar Select2 en los nuevos elementos
    });
    actualizarSelect2();


    // Mostrar modal
    $('#modal-demograficas').modal('show');
}

/**
 * Guarda las respuestas de las demográficas mediante AJAX.
 *
 * @returns {void}
 * @author Andres Morales
 */
function guardarDemograficasModal() {
    var formulario = $('#formulario-demograficas-modal')[0];

    if (!formulario.checkValidity()) {
        formulario.reportValidity();
        return;
    }

    var agenda_id = $('#agenda_id_modal').val();
    let respuestas = [];

    $('select[name^="demografica_"]').each(function() {
        var valor = $(this).val();
        if (valor) {
            respuestas.push({
                demografica_opcion_id: valor
            });
        }
    });

    $('input[name^="demografica_opcion_"]').each(function() {
        var valor = $(this).val();
        var opcion_id = $(this).attr('name').split('_')[2];
        if (valor) {
            respuestas.push({
                demografica_opcion_id: opcion_id,
                respuesta: valor
            });
        }
    });

    $('#btn-guardar-demograficas').prop('disabled', true).text('Guardando...');

    $.ajax({
        type: 'POST',
        url: `/agendas-demograficas-opciones`,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            agenda_id: agenda_id,
            respuestas: JSON.stringify(respuestas)
        },
        success: function(respuesta) {
            if (respuesta.data.redirigir) {
                $('#modal-demograficas').modal({backdrop: 'static', keyboard: false});

                $('button[onclick*="iniciarPruebaConDemograficas"]').prop('disabled', true);
                $('button[onclick*="ejecutarAccionEtapa"]').prop('disabled', true);

                $('#titulo-modal-demograficas').html('<i class="bi bi-hourglass-split me-2"></i>Iniciando prueba');
                $('#subtitulo-modal-demograficas').text('Espera un momento mientras preparamos tu evaluación');

                $('#contenedor-demograficas-modal').html(`
                    <div class="text-center py-5">
                        <div class="spinner-border text-primary mb-3" role="status" style="width: 3rem; height: 3rem;">
                            <span class="visually-hidden">Cargando...</span>
                        </div>
                        <p class="text-body-1 text-gray-10 fw-medium mb-2">Preparando tu evaluación...</p>
                        <p class="text-body-3 text-gray-30">Por favor no cierres esta ventana</p>
                    </div>
                `);

                $('#modal-demograficas .modal-footer').hide();

                mostrarToast('success', 'Datos guardados correctamente');

                window.location.href = `/realizar-prueba/${agenda_id}`;
            }
        },
        error: function() {
            mostrarToast('danger', 'Error al guardar. Intenta nuevamente.');
            $('#btn-guardar-demograficas').prop('disabled', false).text('Continuar');
        }
    });
}

/**
 * Cierra el modal de demográficas y limpia el formulario.
 *
 * @returns {void}
 * @author Andres Morales
 */
function cerrarModalDemograficas() {
    $('button[onclick*="iniciarPruebaConDemograficas"]').prop('disabled', false);
    $('button[onclick*="ejecutarAccionEtapa"]').prop('disabled', false);

    $('#modal-demograficas').modal('hide');
    $('#formulario-demograficas-modal')[0].reset();
    $('#contenedor-demograficas-modal').empty();

    $('#btn-guardar-demograficas').prop('disabled', false).text('Continuar');
}

/**
 * Abre automáticamente el acordeón de una vacante específica.
 *
 * @returns {void}
 * @author Andres Gonzalez
 */
function abrirAcordeonVacante() {
    let parametros_url = new URLSearchParams(window.location.search);
    let vacante_id     = parametros_url.get('vacante_id');

    if (vacante_id) {
        let boton_vacante = $(`#accordionVacante${vacante_id} .accordion-button`);
        if (boton_vacante.length > 0) {
            boton_vacante.click();
        }
    }
}

/**
 * Verifica si hay tareas pendientes reales y redirige a tareas completadas si no las hay.
 * Valida todas las etapas posibles: pruebas psicométricas, videoentrevista, preguntas prefiltro,
 * prueba técnica, documentos para contratación, entrevista y revisión HV.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function verificarYRedirigirSiNoHayTareasPendientes() {
    if (verificarFiltrosAplicados()) {
        return;
    }
    let parametros_url = new URLSearchParams(window.location.search);
    if (parametros_url.get('vacante_id')) {
        return;
    }

    let tiene_tareas_pendientes = verificarTareasPendientesEnDatos(datos_ids);

    if (!tiene_tareas_pendientes) {
        window.location.href = '/tareas-completadas-aplicantes';
    }
}

/**
 * Verifica si hay tareas pendientes en los datos cargados.
 * Analiza todas las etapas posibles para determinar si hay trabajo por hacer.
 *
 * @param {Array} vacantes - Array de vacantes/procesos cargados
 * @returns {boolean} true si hay tareas pendientes, false si no
 * @author Jair Carvajal
 */
function verificarTareasPendientesEnDatos(vacantes) {
    if (!vacantes || vacantes.length === 0) {
        return false;
    }

    let tiene_tareas_pendientes = false;

    vacantes.forEach(function(vacante) {
        if (tiene_tareas_pendientes) return;

        if (vacante.vacante_id === null || vacante.agendas !== undefined) {
            if (vacante.agendas && vacante.agendas.length > 0) {
                vacante.agendas.forEach(function(agenda) {
                    if (agenda.estado_id == '1' || agenda.estado_id == '2') {
                        tiene_tareas_pendientes = true;
                    }
                });
            }
            return;
        }

        if (vacante.etapas && vacante.etapas.length > 0) {
            vacante.etapas.forEach(function(etapa) {
                if (tiene_tareas_pendientes) return;

                let nombre_normalizado = normalizarNombreEtapa(etapa.nombre);
                if (nombre_normalizado === 'PRUEBASPSICOMETRICAS') {
                    if (etapa.agendas && etapa.agendas.length > 0) {
                        etapa.agendas.forEach(function(agenda) {
                            if (agenda.estado_id == '1' || agenda.estado_id == '2') {
                                tiene_tareas_pendientes = true;
                            }
                        });
                    }
                    return;
                }

                // Verificar videoentrevista
                if (nombre_normalizado === 'VIDEOENTREVISTA' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        let usuario_vacante = etapa.usuarios_vacantes[0];

                        // Verificar si la videoentrevista está completa
                        if (usuario_vacante.etapa_video_entrevista_completa != true) {
                            tiene_tareas_pendientes = true;
                        }

                        // Verificar formato de videoentrevista si está configurado
                        let solicita_formato = obtenerConfiguracionPorLlave(etapa.configuraciones, 'solicitar_formato_videoentrevista');
                        if (solicita_formato == '1') {
                            let formato_entrevista = usuario_vacante.formato_entrevista;
                            if (!formato_entrevista || formato_entrevista.descripcion_vacante === null) {
                                tiene_tareas_pendientes = true;
                            }
                        }
                    }
                    return;
                }

                // Verificar preguntas prefiltro
                if (nombre_normalizado === 'PREGUNTASPREFILTRO' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        tiene_tareas_pendientes = true;
                    }
                    return;
                }

                // Verificar prueba técnica
                if (nombre_normalizado === 'PRUEBATECNICA' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        let usuario_vacante = etapa.usuarios_vacantes[0];
                        let pruebas_tecnicas = usuario_vacante.pruebas_tecnicas;

                        // Pendiente si no hay prueba técnica o está en borrador
                        if (!pruebas_tecnicas || pruebas_tecnicas.length === 0 || pruebas_tecnicas[0].borrador == 1) {
                            tiene_tareas_pendientes = true;
                        }
                    }
                    return;
                }

                // Verificar documentos para contratación
                if (nombre_normalizado === 'DOCUMENTOSPARACONTRATACION' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        tiene_tareas_pendientes = true;
                    }
                    return;
                }

                // Verificar entrevista (formato de entrevista)
                if (nombre_normalizado === 'ENTREVISTA' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        let usuario_vacante = etapa.usuarios_vacantes[0];
                        let formato_entrevista = usuario_vacante.formato_entrevista;

                        // Pendiente si no hay formato de entrevista o está vacío
                        if (!formato_entrevista || formato_entrevista.descripcion_vacante === null) {
                            tiene_tareas_pendientes = true;
                        }
                    }
                    return;
                }

                // Verificar revisión HV
                if (nombre_normalizado === 'REVISIONHV' && etapa.activa == 1) {
                    if (etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                        tiene_tareas_pendientes = true;
                    }
                    return;
                }

                // Verificar otras etapas activas con usuarios asignados
                if (etapa.activa == 1 && etapa.usuarios_vacantes && etapa.usuarios_vacantes.length > 0) {
                    tiene_tareas_pendientes = true;
                }
            });
        }
    });

    return tiene_tareas_pendientes;
}

