   485→    /**
   486→     * Generar información de la vacante con IA.
   487→     *
   488→     * @param GenerarVacanteIARequest $request Contenido de la petición.
   489→     * @return JsonResponse
   490→     * @author Daniel Beltrán
   491→     */
   492→    public function generarConIA(GenerarVacanteIARequest $request): JsonResponse {
   493→        $codigo    = Response::HTTP_OK;
   494→        $respuesta = [
   495→            'message' => 'Información generada correctamente'
   496→        ];
   497→
   498→        try {
   499→            $empresa = obtenerEmpresaSesion();
   500→
   501→            $datos_ia = [
   502→                'descripcion' => $request->descripcion
   503→            ];
   504→
   505→            if ($empresa && $empresa->ciudad) {
   506→                $datos_ia['ciudad'] = $empresa->ciudad->nombre;
   507→
   508→                if ($empresa->ciudad->departamento && $empresa->ciudad->departamento->pais) {
   509→                    $datos_ia['pais'] = $empresa->ciudad->departamento->pais->nombre;
   510→                }
   511→            }
   512→
   513→            $respuesta_ia = $this->realizarPeticionIA(
   514→                ruta: 'generar-vacante',
   515→                parametros: $datos_ia,
   516→                contexto_tracking: [
   517→                    'vacante_id' => $request->vacante_id ?? null,
   518→                ]
   519→            );
   520→
   521→            // Extraer solo el 'data' de la respuesta de IA (que ya incluye data y usage)
   522→            $respuesta['data'] = $respuesta_ia['data'] ?? $respuesta_ia;
   523→        } catch (Exception $error) {
   524→            $codigo    = Response::HTTP_BAD_REQUEST;
   525→            $respuesta = [
   526→                'message' => 'Ocurrió un error',
   527→                'errors'  => $error->getMessage()
   528→            ];
   529→        }
   530→
   531→        return new JsonResponse($respuesta, $codigo);
   532→    }
