   112→    public function cambiarOrden(int $id, int $orden): EtapaVacante {
   113→        $etapa       = $this->repositorio->getUno($id);
   114→        $rango_orden = ($orden > $etapa->orden) ? [$etapa->orden, $orden] : [$orden, $etapa->orden];
   115→
   116→        // Obtener las etapas afectadas por el cambio de orden
   117→        $etapas_involucradas = $this->repositorio->obtenerEntreOrden($etapa->vacante_id, $rango_orden)->toArray();
   118→
   119→        // Actualizar el orden de las etapas involucradas
   120→        foreach ($etapas_involucradas as $etapa_involucrada) {
   121→            if ($etapa_involucrada['id'] == $etapa->id) {
   122→                continue;
   123→            }
   124→
   125→            $this->repositorio->actualizar($etapa_involucrada['id'], ['orden' => $etapa_involucrada['orden'] + ($orden > $etapa->orden ? -1 : 1)]);
   126→        }
   127→
   128→        return $this->repositorio->actualizar($id, ['orden' => $orden]);
   129→    }
