   242→    /**
   243→     * Exportar archivos de la etapa en formato ZIP.
   244→     *
   245→     * @param int $etapa_id ID de la etapa.
   246→     * @throws Exception Si la etapa no existe.
   247→     * @throws Exception Si no hay archivos disponibles para descargar.
   248→     * @throws Exception Si no se pudo crear el archivo ZIP.
   249→     * @throws Exception Si el archivo ZIP no se creó correctamente.
   250→     * @return BinaryFileResponse
   251→     * @author Andres Gonzalez
   252→     */
   253→    public function exportarArchivosZip(int $etapa_id): BinaryFileResponse {
   254→        $etapa = $this->repositorio->getUno($etapa_id);
   255→
   256→        if (!$etapa) {
   257→            throw new Exception('Etapa no encontrada', 404);
   258→        }
   259→
   260→        if (empty($etapa->archivos) || count($etapa->archivos) === 0) {
   261→            throw new Exception('No hay archivos disponibles para descargar en esta etapa', 404);
   262→        }
   263→
   264→        $archivo_zip        = new ZipArchive();
   265→        $nombre_archivo_zip = 'archivos-etapa-' . $etapa->nombre . '-' . date('Y-m-d_H-i-s') . '.zip';
   266→        $ruta_temporal      = storage_path('app/temp');
   267→        $url_zip            = $ruta_temporal . '/' . $nombre_archivo_zip;
   268→
   269→        if (!file_exists($ruta_temporal)) {
   270→            mkdir($ruta_temporal, 0755, true);
   271→        }
   272→
   273→        if ($archivo_zip->open($url_zip, ZipArchive::CREATE | ZipArchive::OVERWRITE) !== true) {
   274→            throw new Exception('No se pudo crear el archivo ZIP');
   275→        }
   276→
   277→        foreach ($etapa->archivos as $archivo) {
   278→            $ruta_completa = storage_path('app/' . $archivo->ruta);
   279→
   280→            if (Storage::exists($archivo->ruta)) {
   281→                $archivo_zip->addFile($ruta_completa, $archivo->nombre_original_archivo);
   282→            }
   283→        }
   284→
   285→        $archivo_zip->close();
   286→
   287→        if (!file_exists($url_zip)) {
   288→            throw new Exception("El archivo ZIP no se creó correctamente: {$url_zip}");
   289→        }
   290→
   291→        $respuesta = response()->download($url_zip, $nombre_archivo_zip);
   292→        $respuesta->deleteFileAfterSend(true);
   293→
   294→        return $respuesta;
   295→    }
