   297→    /**
   298→     * Obtener todas las etapas de una vacante con sus aplicantes.
   299→     *
   300→     * @param Request $request Contenido de la petición.
   301→     * @return array
   302→     * @author Andres Gonzalez
   303→     * @author Andres Morales
   304→     */
   305→    public function obtenerEtapasAplicantes(Request $request): array {
   306→        $etapas              = $this->repositorio->getTodoAplicante($request);
   307→        $etapas_con_usuarios = [];
   308→
   309→        // Obtener la vacante con su proceso para validar las pruebas
   310→        $vacante = $this->vacante_repositorio->getUno($request->vacante_id);
   311→
   312→        // Agregar adecuación a cada usuario en usuarios_vacantes y filtrar si es necesario
   313→        foreach ($etapas as $etapa) {
   314→            $usuarios_filtrados = [];
   315→
   316→            if ($etapa->nombre === EtapaVacante::PRUEBA_TECNICA_NOMBRE) {
   317→                $configuraciones_prueba_tecnica = $this->obtenerConfiguracionesPruebaTecnica($etapa->id);
   318→                $etapa->prueba_cargada = $configuraciones_prueba_tecnica['prueba_cargada'] ?? false;
   319→            }
   320→
   321→            foreach ($etapa->usuariosVacantes as $usuario_vacante) {
   322→                $usuario_vacante->adecuacion               = $this->etapa_vacante_usuario_servicio->obtenerAdecuacionUsuario($usuario_vacante->usuario_id, $request->vacante_id);
   323→                $usuario_vacante->etapa_completada         = $this->etapa_vacante_usuario_servicio->verificarEtapaCompletada($usuario_vacante->id);
   324→                $usuario_vacante->tiene_pruebas_requeridas = $this->validarPruebasRequeridas($usuario_vacante->usuario_id, $vacante);
   325→                $usuario_vacante->prueba_tecnica           = $this->obtenerEstadoPruebaTecnicaCandidato($usuario_vacante->id);
   326→
   327→                // Agregar formato_entrevista_completado solo para etapas de Entrevista y Video Entrevista
   328→                if ($etapa->nombre === EtapaVacante::VIDEO_ENTREVISTA_NOMBRE) {
   329→                    $usuario_vacante->formato_entrevista_completado = $this->etapa_vacante_usuario_servicio->verificarFormatoEntrevista(
   330→                        $usuario_vacante,
   331→                        MovimientoVacante::SOLICITUD_VIDEOENTREVISTA_ID,
   332→                        'solicitar_formato_videoentrevista'
   333→                    );
   334→                } elseif ($etapa->nombre === EtapaVacante::ENTREVISTA_NOMBRE) {
   335→                    $usuario_vacante->formato_entrevista_completado = $this->etapa_vacante_usuario_servicio->verificarFormatoEntrevista(
   336→                        $usuario_vacante,
   337→                        MovimientoVacante::SOLICITUD_ENTREVISTA_ID,
   338→                        'solicitar_formato_entrevista'
   339→                    );
   340→                }
   341→
   342→                // Filtrar por nivel de adecuación si se especifica
   343→                if ($request->filled('nivel_adecuacion')) {
   344→                    $nivel      = strtolower($request->nivel_adecuacion);
   345→                    $adecuacion = $usuario_vacante->adecuacion;
   346→
   347→                    $incluir = match ($nivel) {
   348→                        'bajo'  => $adecuacion >= 0 && $adecuacion <= 40,
   349→                        'medio' => $adecuacion >= 41 && $adecuacion <= 70,
   350→                        'alto'  => $adecuacion >= 71 && $adecuacion <= 100,
   351→                        default => true
   352→                    };
   353→
   354→                    if ($incluir) {
   355→                        $usuarios_filtrados[] = $usuario_vacante;
   356→                    }
   357→                } else {
   358→                    $usuarios_filtrados[] = $usuario_vacante;
   359→                }
   360→            }
   361→
   362→            // Ordenar usuarios por adecuación de mayor a menor
   363→            usort($usuarios_filtrados, function ($a, $b) {
   364→                return $b->adecuacion <=> $a->adecuacion;
   365→            });
   366→
   367→            // Reemplazar usuarios con los filtrados
   368→            $etapa->setRelation('usuariosVacantes', collect($usuarios_filtrados));
   369→
   370→            if ($request->filled('nivel_adecuacion')) {
   371→                if (count($usuarios_filtrados) > 0) {
   372→                    $etapas_con_usuarios[] = $etapa;
   373→                }
   374→            } else {
   375→                $etapas_con_usuarios[] = $etapa;
   376→            }
   377→        }
   378→
   379→        return [
   380→            'etapas'      => $etapas_con_usuarios,
   381→            'descartados' => $this->obtenerUsuariosDescartados($request)
   382→        ];
   383→    }
