   505→    public function calcularDiasDuracionProceso(int $id): int {
   506→        $etapas_vacantes = $this->repositorio->getTodo(new Request(['vacante_id' => $id, 'activa' => true]));
   507→        $dias_total      = 0;
   508→
   509→        $mapeo_configuraciones_dias = [
   510→            EtapaVacante::REVISION_HV_NOMBRE             => 'caducar_acceso_despues_de_dias_hv',
   511→            EtapaVacante::PREGUNTAS_PREFILTRO_NOMBRE     => 'caducar_acceso_despues_de_dias_prefiltro',
   512→            EtapaVacante::PRUEBA_TECNICA_NOMBRE          => 'caducar_acceso_despues_de_dias_prueba_tecnica',
   513→            EtapaVacante::VIDEO_ENTREVISTA_NOMBRE        => 'caducar_acceso_despues_de_dias_videoentrevista',
   514→            EtapaVacante::ENTREVISTA_NOMBRE              => 'caducar_acceso_despues_de_dias_entrevista',
   515→            EtapaVacante::DOCUMENTOS_CONTRATACION_NOMBRE => 'caducar_acceso_despues_de_dias_documentos'
   516→        ];
   517→
   518→        foreach ($etapas_vacantes as $etapa) {
   519→            $configuraciones = app(VacanteService::class)->obtenerConfiguracionesEtapaAplicante($etapa->id);
   520→
   521→            if ($etapa->nombre == EtapaVacante::PRUEBAS_PSICOMETRICAS_NOMBRE) {
   522→                $caducar_acceso_despues_fecha = $this->configuracion_modelo_servicio->obtenerValorLlaveConfiguracion($configuraciones, 'caducar_acceso_despues_de_fecha_pruebas_psicometricas');
   523→                $caducar_acceso_despues_dias  = $this->configuracion_modelo_servicio->obtenerValorLlaveConfiguracion($configuraciones, 'caducar_acceso_despues_de_dias_pruebas_psicometricas');
   524→
   525→                if (!empty($caducar_acceso_despues_fecha)) {
   526→                    $fecha_configurada = Carbon::parse($caducar_acceso_despues_fecha);
   527→                    $fecha_creacion    = Carbon::parse($etapa->created_at);
   528→                    $dias_total += $fecha_creacion->diffInDays($fecha_configurada);
   529→                } else {
   530→                    $dias_total += $caducar_acceso_despues_dias;
   531→                }
   532→
   533→                continue;
   534→            }
   535→
   536→            if (isset($mapeo_configuraciones_dias[$etapa->nombre])) {
   537→                $dias = $this->configuracion_modelo_servicio->obtenerValorLlaveConfiguracion($configuraciones, $mapeo_configuraciones_dias[$etapa->nombre]);
   538→
   539→                if (!empty($dias)) {
   540→                    $dias_total += $dias;
   541→                }
   542→            }
   543→        }
   544→
   545→        return $dias_total;
   546→    }
