   568→    /**
   569→     * Eliminar (desactivar) etapa de prueba técnica.
   570→     * Si tiene candidatos activos y la siguiente etapa no es "Contratados", los mueve a la siguiente etapa.
   571→     *
   572→     * @param int $etapa_vacante_id ID de la etapa.
   573→     * @throws Exception
   574→     * @return void
   575→     * @author Andres Morales
   576→     * @author Andres Gonzalez
   577→     */
   578→    public function eliminarEtapaPruebaTecnica(int $etapa_vacante_id): void {
   579→        $etapa_vacante = $this->repositorio->getUno($etapa_vacante_id);
   580→
   581→        if ($etapa_vacante->nombre !== 'Prueba técnica') {
   582→            throw new Exception('Esta etapa no es de prueba técnica', 400);
   583→        }
   584→
   585→        $candidatos_activos = $etapa_vacante->usuariosVacantes()
   586→            ->where('activo', true)
   587→            ->get();
   588→
   589→        if ($candidatos_activos->count() > 0) {
   590→            $etapa_siguiente = $this->repositorio->obtenerEtapaSiguiente(
   591→                $etapa_vacante->vacante_id,
   592→                $etapa_vacante->orden
   593→            );
   594→
   595→            if (!$etapa_siguiente) {
   596→                throw new Exception('No se encontró una etapa siguiente para mover los candidatos', 400);
   597→            }
   598→
   599→            // Si la siguiente etapa es Contratados, mover a la etapa anterior
   600→            if ($etapa_siguiente->nombre == EtapaVacante::CONTRATADOS_NOMBRE) {
   601→                $etapa_anterior = $this->repositorio->obtenerEtapaAnterior($etapa_vacante->vacante_id, $etapa_vacante->orden);
   602→
   603→                if (!$etapa_anterior) {
   604→                    throw new Exception('No se encontró una etapa anterior para mover los candidatos', 400);
   605→                }
   606→
   607→                foreach ($candidatos_activos as $candidato_activo) {
   608→                    $this->etapa_vacante_usuario_repositorio->eliminar($candidato_activo->id);
   609→                    $etapa_anterior_usuario = $this->etapa_vacante_usuario_repositorio->getUnoAvanzado(new Request(['usuario_id' => $candidato_activo->usuario_id, 'etapa_vacante_id' => $etapa_anterior->id]));
   610→
   611→                    if ($etapa_anterior_usuario) {
   612→                        $this->etapa_vacante_usuario_repositorio->actualizar($etapa_anterior_usuario->id, ['activo' => true]);
   613→                    }
   614→                }
   615→            } else {
   616→                foreach ($candidatos_activos as $candidato_activo) {
   617→                    $this->etapa_vacante_usuario_servicio->moverAplicanteEtapaManual($candidato_activo->id);
   618→                    $this->etapa_vacante_usuario_repositorio->eliminar($candidato_activo->id);
   619→                }
   620→            }
   621→        }
   622→
   623→        foreach ($etapa_vacante->archivos as $archivo) {
   624→            $this->archivo_servicio->eliminarArchivoDesdeRuta($archivo->ruta);
   625→            $this->archivo_servicio->repositorio->eliminar($archivo->id);
   626→        }
   627→
   628→        $this->repositorio->actualizar($etapa_vacante_id, ['activa' => false]);
   629→    }
