 * @return Collection
 * @author Andres Gonzalez
 * @author Andres Morales
 * @author Jair Carvajal
 * @author José Manuel Jiménez
 */
public function getTodoAplicante(Request $request): Collection {
    $request->merge(['aplicante_id' => Auth::id()]);

    return $this->modelo::select('id', 'empresa_id', 'usuario_id', 'ciudad_id', 'estado_id', 'nombre_vacante', 'cantidad_vacantes', 'salario', 'salario_maximo', 'activo', 'automatizar_etapas', 'created_at', 'updated_at')
    ->with([
        'empresa:id,nombre_comercial,razon_social',
        'ciudad:id,departamento_id,nombre',
        'ciudad.departamento:id,pais_id,nombre',
        'ciudad.departamento.pais:id,nombre',
        'etapas' => function ($consulta) use ($request) {
            $consulta->select('id', 'vacante_id', 'nombre', 'orden', 'fija', 'editable', 'activa', 'created_at', 'updated_at')
                ->withSum('preguntasOfertaLaboral as duracion', 'tiempo_respuesta')
                ->with([
                    'usuariosVacantes' => function ($sub_consulta) use ($request) {
                        $sub_consulta->select('id', 'usuario_id', 'etapa_vacante_id', 'fecha_notificacion', 'fecha_ejecucion', 'activo', 'updated_at')
                            ->where('usuario_id', $request->aplicante_id)
                            ->whereNotNull('fecha_notificacion')
                            ->when(!$request->completadas, function ($consulta_vacantes) {
                                $consulta_vacantes->where('activo', true);
                            })
                            ->with(['archivos:id,modelo,modelo_id,nombre,nombre_original_archivo,ruta',
                                'pruebasTecnicas:id,enlace,etapa_vacante_usuario_id,observacion_candidato,borrador',
                                'pruebasTecnicas.archivos:id,modelo,modelo_id,nombre,nombre_original_archivo,ruta',
                                'formatoEntrevista:id,etapa_vacante_usuario_id,descripcion_vacante,updated_at'
                            ]);
                    },
                    'archivos:id,modelo,modelo_id,nombre,nombre_original_archivo,ruta'
                ])
                ->whereHas('usuariosVacantes', function ($sub_consulta) use ($request) {
                    $sub_consulta->where('usuario_id', $request->aplicante_id)
                        ->whereNotNull('fecha_notificacion')
                        ->when(!$request->completadas, function ($completas_request) {
                            $completas_request->where('activo', true);
                        });
                })
                ->whereNotIn('nombre', [EtapaVacante::CONTRATADOS_NOMBRE, EtapaVacante::DESCARTADOS_NOMBRE])
                ->orderBy('orden', 'ASC');
        },
        'estado:id,nombre'
    ])
    ->withCount(['etapas as total_etapas' => function ($consulta) {
        $consulta->where('activa', true)
            ->whereNotIn('nombre', [EtapaVacante::CONTRATADOS_NOMBRE, EtapaVacante::DESCARTADOS_NOMBRE]);
    }])
    ->when(!$request->completadas, function ($consulta) {
        $consulta->where('estado_id', EstadoVacante::ACTIVADA_ID);
    })
    ->when($request->filled('estado_id'), function ($consulta) use ($request) {
        $consulta->where('estado_id', $request->estado_id);
    })
    ->when($request->filled('fecha_creacion_desde'), function ($consulta) use ($request) {
        $campo_fecha = $request->completadas ? 'updated_at' : 'created_at';
        $consulta->whereDate($campo_fecha, '>=', $request->fecha_creacion_desde);
    })
    ->when($request->filled('fecha_creacion_hasta'), function ($consulta) use ($request) {
        $campo_fecha = $request->completadas ? 'updated_at' : 'created_at';
        $consulta->whereDate($campo_fecha, '<=', $request->fecha_creacion_hasta);
    })
    ->when($request->completadas && $request->filled('filtro_estado_tarea'), function ($consulta) use ($request) {
        $consulta->whereHas('etapas.usuariosVacantes', function ($sub_consulta) use ($request) {
            $sub_consulta->where('activo', $request->filtro_estado_tarea);
            if ((int) $request->filtro_estado_tarea === 1) {
                $sub_consulta->where('fecha_notificacion', '>=', now());
            }
        });
    })
    ->when($request->filled('aplicante_id'), function ($consulta) use ($request) {
        $consulta->whereHas('usuariosVacantes', function ($sub_consulta) use ($request) {
            $sub_consulta->where('usuario_id', $request->aplicante_id);
        });
    })
    ->whereDoesntHave('etapas.usuariosVacantes', function ($consulta) use ($request) {
        $consulta->where('usuario_id', $request->aplicante_id)
            ->whereNotNull('motivo_abandono');
    })
    ->whereDoesntHave('etapas.usuariosVacantes', function ($consulta) use ($request) {
        $consulta->where('usuario_id', $request->aplicante_id)
            ->whereNotNull('fecha_notificacion')
            ->whereHas('etapa', function ($etapa_consulta) {
                $etapa_consulta->whereIn('nombre', [EtapaVacante::DESCARTADOS_NOMBRE]);
            });
    })
    ->orderBy('created_at', 'DESC')
    ->get();
}

