public function getUnoAvanzado(Request $request): ?EtapaVacanteUsuario {
    return $this->modelo::select('id', 'usuario_id', 'etapa_vacante_id', 'puntaje', 'puntaje_ia', 'notas_ia', 'fecha_notificacion', 'fecha_ejecucion', 'motivo_abandono', 'activo')
    ->when($request->filled('id'), fn($consulta) => $consulta->where('id', $request->id))
    ->when($request->filled('usuario_id'), fn($consulta) => $consulta->where('usuario_id', $request->usuario_id))
    ->when($request->filled('etapa_vacante_id'), fn($consulta) => $consulta->where('etapa_vacante_id', $request->etapa_vacante_id))
    ->when($request->filled('vacante_id'), function ($consulta) use ($request) {
        $consulta->whereHas('etapa', fn($etapa) => $etapa->where('vacante_id', $request->vacante_id));
    })
    ->when($request->filled('nombre_etapa'), function ($consulta) use ($request) {
        $consulta->whereHas('etapa', fn($etapa) => $etapa->where('nombre', $request->nombre_etapa));
    })
    ->when($request->filled('incluir_etapa') && $request->incluir_etapa, fn($consulta) => $consulta->with('etapa:id,nombre'))
    ->when($request->filled('incluir_archivos'), fn($consulta) => $consulta->with('archivos:id,modelo,modelo_id,nombre,nombre_original_archivo,ruta'))
    ->when($request->filled('incluir_formato_entrevista'), fn($consulta) => $consulta->with('formatoEntrevista:id,etapa_vacante_usuario_id'))
    ->when($request->filled('incluir_transcripcion'), fn($consulta) => $consulta->with('transcripcion:id,etapa_vacante_usuario_id,texto'))
    ->when($request->filled('incluir_comentarios'), fn($consulta) => $consulta->with([
        'comentarios:id,etapa_vacante_usuario_id,usuario_id,comentario',
        'comentarios.usuario:id,nombres,apellidos'
    ]))
    ->when($request->filled('incluir_vacante') && $request->incluir_vacante, function ($consulta) {
        $consulta->with([
            'vacante:vacantes.id,empresa_id,modalidad_trabajo_id,estado_id,nombre_vacante,cantidad_vacantes,salario,salario_maximo,automatizar_etapas',
            'vacante.modalidadTrabajo:id,nombre',
